(()=>{'use strict';
const $=id=>document.getElementById(id),canvas=$('canvas'),ctx=canvas.getContext('2d'),N=24,S=25;
const dirs={up:{x:0,y:-1},down:{x:0,y:1},left:{x:-1,y:0},right:{x:1,y:0}};
let snake,dir,queue,food,score=0,best=0,state='ready',timer=null,touch=null;
try{best=Number(localStorage.getItem('worm-best'))||0;}catch{}$('best').textContent=best;
function reset(){snake=[{x:10,y:12},{x:9,y:12},{x:8,y:12},{x:7,y:12}];dir=dirs.right;queue=[];score=0;$('score').textContent=0;food=spawn();}
function spawn(){const cells=[];for(let y=0;y<N;y++)for(let x=0;x<N;x++)if(!snake.some(p=>p.x===x&&p.y===y))cells.push({x,y});return cells[Math.floor(Math.random()*cells.length)]||null;}
function draw(){ctx.fillStyle='#e8edda';ctx.fillRect(0,0,600,600);ctx.fillStyle='#d7dfc9';for(let y=0;y<N;y++)for(let x=0;x<N;x++){ctx.beginPath();ctx.arc(x*S+12.5,y*S+12.5,1.1,0,Math.PI*2);ctx.fill();}if(food){ctx.fillStyle='#db7450';ctx.beginPath();ctx.arc(food.x*S+12.5,food.y*S+14,9,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#527044';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(food.x*S+13,food.y*S+6);ctx.lineTo(food.x*S+17,food.y*S+2);ctx.stroke();}snake.slice().reverse().forEach((p,i)=>{ctx.fillStyle=i===snake.length-1?'#335e3c':i%2?'#7c9b56':'#8eab63';ctx.beginPath();ctx.roundRect(p.x*S+1,p.y*S+1,S-2,S-2,8);ctx.fill();});const h=snake[0],px=-dir.y,py=dir.x;for(const side of [-1,1]){const x=h.x*S+12.5+dir.x*5+px*side*5,y=h.y*S+12.5+dir.y*5+py*side*5;ctx.fillStyle='#fffdf5';ctx.beginPath();ctx.arc(x,y,3.6,0,Math.PI*2);ctx.fill();ctx.fillStyle='#1d3328';ctx.beginPath();ctx.arc(x+dir.x,y+dir.y,1.7,0,Math.PI*2);ctx.fill();}}
function clock(){clearInterval(timer);timer=setInterval(step,Number($('speed').value));}
function start(){reset();state='playing';$('overlay').hidden=true;$('pause').disabled=false;$('pause').textContent='일시정지';$('status').textContent='사과를 향해 출발!';clock();draw();}
function finish(won=false){state='over';clearInterval(timer);$('overlay').hidden=false;$('title').textContent=won?'정원을 가득 채웠어요!':'다시 한번, 꼬물꼬물!';$('message').textContent=`이번 점수 ${score}점 · 최고 기록 ${best}점`;$('start').textContent='다시 시작 ↗';$('pause').disabled=true;$('status').textContent=won?'완벽한 정원 완성':'게임 종료';}
function step(){if(state!=='playing')return;if(queue.length)dir=queue.shift();const h={x:snake[0].x+dir.x,y:snake[0].y+dir.y},eat=food&&h.x===food.x&&h.y===food.y;const body=eat?snake:snake.slice(0,-1);if(h.x<0||h.y<0||h.x>=N||h.y>=N||body.some(p=>p.x===h.x&&p.y===h.y)){finish();return;}snake.unshift(h);if(eat){score+=10;$('score').textContent=score;if(score>best){best=score;$('best').textContent=best;try{localStorage.setItem('worm-best',String(best));}catch{}}food=spawn();if(!food){draw();finish(true);return;}}else snake.pop();draw();}
function turn(name){if(state!=='playing'||queue.length>=2)return;const next=dirs[name],last=queue.length?queue[queue.length-1]:dir;if(next.x===-last.x&&next.y===-last.y||next.x===last.x&&next.y===last.y)return;queue.push(next);}
function pause(){if(state!=='playing'&&state!=='paused')return;const paused=state==='playing';state=paused?'paused':'playing';$('pause').textContent=paused?'계속하기':'일시정지';$('overlay').hidden=!paused;$('title').textContent='잠깐 쉬어 가요';$('message').textContent='준비되면 다시 이어서 달려요.';$('start').textContent='계속하기 ↗';$('status').textContent=paused?'일시정지 중':'사과를 향해 출발!';if(paused)clearInterval(timer);else clock();}
$('start').onclick=()=>state==='paused'?pause():start();$('pause').onclick=pause;$('speed').onchange=()=>{if(state==='playing')clock();};document.querySelectorAll('[data-dir]').forEach(b=>b.onclick=()=>turn(b.dataset.dir));document.addEventListener('keydown',e=>{if(e.target.tagName==='SELECT')return;const name={ArrowUp:'up',ArrowDown:'down',ArrowLeft:'left',ArrowRight:'right',w:'up',s:'down',a:'left',d:'right'}[e.key]||({w:'up',s:'down',a:'left',d:'right'})[e.key.toLowerCase()];if(name){e.preventDefault();turn(name);}else if(e.code==='Space'&&e.target.tagName!=='BUTTON'){e.preventDefault();if(state==='ready'||state==='over')start();else pause();}});canvas.addEventListener('pointerdown',e=>{touch={x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId);});canvas.addEventListener('pointerup',e=>{if(!touch)return;const dx=e.clientX-touch.x,dy=e.clientY-touch.y;touch=null;if(Math.max(Math.abs(dx),Math.abs(dy))<12)return;turn(Math.abs(dx)>Math.abs(dy)?dx>0?'right':'left':dy>0?'down':'up');});canvas.addEventListener('pointercancel',()=>touch=null);document.addEventListener('visibilitychange',()=>{if(document.hidden&&state==='playing')pause();});reset();draw();
})();
